       _streamingTracker = null;

  JsonCodableDecoder.fromReader(
    JsonTokenReader reader, {
    this.userInfo = const {},
  }) : _bytes = null,
       _decoded = null,
       _reader = reader,
       _streamingTracker = null,
       _origin = null,
       _parent = null,
       _segment1 = null,
       _segment2 = null;

  JsonCodableDecoder._fromReaderAtStart(
    JsonTokenReader reader,
    this._bytes, {
    this.userInfo = const {},
    this._streamingTracker,
